INSERT INTO public.applications VALUES ('5b6fb13e-2bf0-5c1f-9b9e-511ae26479cd', 'fd26b374-6ff8-5831-92ec-b2df993bc8f1', '74f4f516-af9b-5ea0-9632-b891b6db72bc', 'Em chào anh/chị. Em là người ham học hỏi, từng tham gia một số dự án có công nghệ tương tự yêu cầu. Em sẵn sàng làm bài kiểm tra hoặc phỏng vấn vào thời gian anh/chị thuận tiện.', '/uploads/cvs/demo-cv-dang-thi-nga.pdf', 'INTERVIEW', '2026-10-23 02:51:49.755+07', '2026-10-27 09:09:36.062+07');
INSERT INTO public.applications VALUES ('f62a0fdd-e2eb-51fe-95f4-e4014f613c43', '457f9164-6428-5be8-927d-744fb8587b92', '74f4f516-af9b-5ea0-9632-b891b6db72bc', 'Xin chào công ty, tôi quan tâm đến vị trí này vì môi trường và sản phẩm của công ty. Tôi có thể bắt đầu làm việc sau 2 tuần kể từ khi nhận offer.', '/uploads/cvs/demo-cv-ly-ngoc-hanh.pdf', 'PENDING', '2026-10-29 11:53:39.184+07', '2026-10-29 11:53:39.184+07');
