INSERT INTO public.applications VALUES ('41916ea5-7002-5479-bd2e-23d4200350f6', '1d10ae50-a829-57b2-9703-e7b9bcd8301a', 'bad3b17d-ebec-5f96-8fb0-81314af1d45f', 'Kính gửi nhà tuyển dụng, tôi có kinh nghiệm thực tế với các công nghệ trong yêu cầu và mong muốn được đóng góp cho đội ngũ. Rất mong nhận được phản hồi từ quý công ty.', '/uploads/cvs/demo-cv-vo-tuan-nhan.pdf', 'VIEWED', '2026-10-15 00:13:44.417+07', '2026-10-23 06:03:22.26+07');
