INSERT INTO public.applications VALUES ('e9d00b15-629f-5ef2-913e-03afd57dde0e', '94aa8f88-8561-5ee9-9702-7934d7c631fa', '152a159c-e118-5bd8-b6d4-cf9fa6ad1af8', 'Em chào anh/chị. Em là người ham học hỏi, từng tham gia một số dự án có công nghệ tương tự yêu cầu. Em sẵn sàng làm bài kiểm tra hoặc phỏng vấn vào thời gian anh/chị thuận tiện.', '/uploads/cvs/demo-cv-vo-kim-thao.pdf', 'VIEWED', '2026-10-21 22:30:35.147+07', '2026-10-25 08:10:12.386+07');
INSERT INTO public.applications VALUES ('0aae199d-b1d2-599e-8ef5-d65f7561b17d', '14e3ae09-d084-548b-bcaa-21abff63df1a', '152a159c-e118-5bd8-b6d4-cf9fa6ad1af8', 'Kính gửi nhà tuyển dụng, tôi có kinh nghiệm thực tế với các công nghệ trong yêu cầu và mong muốn được đóng góp cho đội ngũ. Rất mong nhận được phản hồi từ quý công ty.', '/uploads/cvs/demo-cv-le-hong-anh.pdf', 'HIRED', '2026-10-24 13:09:07.133+07', '2026-10-27 03:15:41.422+07');
