INSERT INTO public.applications VALUES ('85728163-8f67-5999-8685-01fe0c228cd1', 'e054edcb-a716-5cf7-b9aa-35c12595b4f0', '54b51c1b-480c-5c97-b522-91341866a5e4', 'Xin chào công ty, tôi quan tâm đến vị trí này vì môi trường và sản phẩm của công ty. Tôi có thể bắt đầu làm việc sau 2 tuần kể từ khi nhận offer.', '/uploads/cvs/demo-cv-ngo-huu-phuc.pdf', 'INTERVIEW', '2026-10-22 14:27:16.09+07', '2026-10-28 05:12:13.823+07');
