INSERT INTO public.applications VALUES ('b9481964-500d-58f6-8c3c-ef962fba385b', '2adcc556-aa24-5982-8500-6093ef6054c0', '54b51c1b-480c-5c97-b522-91341866a5e4', 'Xin chào công ty, tôi quan tâm đến vị trí này vì môi trường và sản phẩm của công ty. Tôi có thể bắt đầu làm việc sau 2 tuần kể từ khi nhận offer.', '/uploads/cvs/demo-cv-vu-bao-lan.pdf', 'VIEWED', '2026-10-17 03:46:53.652+07', '2026-10-23 05:31:15.229+07');
INSERT INTO public.applications VALUES ('f0fe447f-a73b-55b5-b586-65d0573e4727', '14e3ae09-d084-548b-bcaa-21abff63df1a', '54b51c1b-480c-5c97-b522-91341866a5e4', 'Kính gửi nhà tuyển dụng, tôi có kinh nghiệm thực tế với các công nghệ trong yêu cầu và mong muốn được đóng góp cho đội ngũ. Rất mong nhận được phản hồi từ quý công ty.', '/uploads/cvs/demo-cv-le-hong-anh.pdf', 'REJECTED', '2026-10-19 00:37:12.078+07', '2026-10-27 22:48:09.576+07');
