INSERT INTO public.applications VALUES ('abd61450-0769-5437-bb90-4f2c2832ab08', '8288f5fd-3357-5e02-9a66-3b7c07a3e2d6', '5e29bcb4-bb83-5ceb-8a84-b04b85384acb', 'Xin chào công ty, tôi quan tâm đến vị trí này vì môi trường và sản phẩm của công ty. Tôi có thể bắt đầu làm việc sau 2 tuần kể từ khi nhận offer.', '/uploads/cvs/demo-cv-phan-thu-vy.pdf', 'REJECTED', '2026-10-21 07:44:32.174+07', '2026-10-25 10:37:17.504+07');
INSERT INTO public.applications VALUES ('c227da60-7932-5ab2-9297-f8daca90fdd2', '9ce67a35-129f-5822-9658-a883a80d1f31', '5e29bcb4-bb83-5ceb-8a84-b04b85384acb', 'Em chào anh/chị. Em là người ham học hỏi, từng tham gia một số dự án có công nghệ tương tự yêu cầu. Em sẵn sàng làm bài kiểm tra hoặc phỏng vấn vào thời gian anh/chị thuận tiện.', '/uploads/cvs/demo-cv-le-tuan-khoa.pdf', 'VIEWED', '2026-10-18 13:32:54.588+07', '2026-10-25 06:51:58.83+07');
INSERT INTO public.applications VALUES ('f3dc610f-3af5-56b3-b6df-ed175623205e', 'aea768c2-ceb8-5a22-8039-c405fca08a9c', '5e29bcb4-bb83-5ceb-8a84-b04b85384acb', 'Em chào anh/chị. Em là người ham học hỏi, từng tham gia một số dự án có công nghệ tương tự yêu cầu. Em sẵn sàng làm bài kiểm tra hoặc phỏng vấn vào thời gian anh/chị thuận tiện.', '/uploads/cvs/demo-cv-ly-minh-huy.pdf', 'REJECTED', '2026-10-27 18:20:28.408+07', '2026-10-29 08:50:31.329+07');
INSERT INTO public.applications VALUES ('79b27e5c-dd6f-5fbb-ad5b-7e61bbc84aeb', '427341e5-0181-59ad-bdb1-ec22ba1914f8', '5e29bcb4-bb83-5ceb-8a84-b04b85384acb', 'Chào anh/chị, em đã đọc kỹ mô tả công việc và thấy kỹ năng của mình phù hợp với vị trí này. Em đính kèm hồ sơ và rất mong có cơ hội trao đổi thêm. Em xin cảm ơn.', '/uploads/cvs/demo-cv-bui-anh-trung.pdf', 'REJECTED', '2026-10-18 15:42:28.938+07', '2026-10-24 13:59:02.065+07');
