INSERT INTO public.candidate_profiles VALUES ('2adcc556-aa24-5982-8500-6093ef6054c0', 'e5457bad-b9c4-5188-8f44-c730bbbcdb51', 'Fresher React Developer', 'Mình vừa tốt nghiệp và đã thực hiện nhiều đồ án, dự án cá nhân về giao diện web với React. Thành thạo React, JavaScript, HTML/CSS và đã làm quen với Tailwind CSS, Figma. Có tinh thần trách nhiệm, giao tiếp tốt và sẵn sàng làm việc từ xa hoặc linh hoạt thời gian.', '0568202444', 'Đà Nẵng', 'https://github.com/lan-vu1', NULL, NULL, '/uploads/cvs/demo-cv-vu-bao-lan.pdf', 'CV_VuBaoLan.pdf', 0.00, '2026-03-26 02:56:27.162+07', '2026-03-26 01:56:27.162+07', '{"show_cv": true, "show_email": true, "show_links": true, "show_phone": true, "show_address": true, "is_searchable": true, "show_experiences": true, "show_introduction": true, "show_devhub_projects": true}');
