INSERT INTO public.candidate_profiles VALUES ('c4ef8913-96a9-54d0-9c53-02b2cff6c693', '69770111-7bfe-53bd-a59d-75d33fd8ec23', 'Fullstack Web Developer', 'Mình có 3 năm kinh nghiệm về ứng dụng web fullstack (React & Node.js). Thành thạo React, Node.js, PostgreSQL và đã làm quen với REST API, Docker. Quen làm việc theo Agile/Scrum, thích học hỏi công nghệ mới và chia sẻ kiến thức với đồng đội.', '0551080249', 'TP. Hồ Chí Minh', 'https://github.com/thinh-ngo2', NULL, NULL, '/uploads/cvs/demo-cv-ngo-minh-thinh.pdf', 'CV_NgoMinhThinh.pdf', 0.00, '2026-09-15 03:03:25.866+07', '2026-09-15 02:03:25.866+07', '{"show_cv": true, "show_email": true, "show_links": true, "show_phone": true, "show_address": true, "is_searchable": true, "show_experiences": true, "show_introduction": true, "show_devhub_projects": true}');
