INSERT INTO public.project_applications VALUES ('00d5f656-85b1-4e4b-abcf-dd7f2c609f5f', '986306d2-ccda-42e3-bf64-d6f894ec68bb', 'f37c66fb-d3cc-4aad-a7e3-6ae8b88dafa8', 'Tôi có nhiều kinh nghiệm làm giao diện React Dashboard và cam kết hoàn thành đúng deadline.', NULL, 'ACCEPTED', NULL, NULL, NULL, '2026-09-26 17:32:17.268+07', '2026-10-10 18:48:18.706+07');
INSERT INTO public.project_applications VALUES ('08d927df-9d37-4554-8959-504f718dc0f2', 'ba2deb92-cee0-401d-b797-4d862a7d3e70', 'd2acdae6-3cbe-4d92-825e-a9a0bb84cf8f', 'Tôi thành thạo Node.js và PostgreSQL, tự tin làm tốt hệ thống này.', NULL, 'ACCEPTED', NULL, NULL, NULL, '2026-09-26 17:32:17.268+07', '2026-10-10 18:48:43.278+07');
INSERT INTO public.project_applications VALUES ('f60b16e0-3eb4-5714-b74f-66c76d96f85a', 'ff1fadb5-4c86-5ddb-b63f-da5a65bdded7', 'c1a745e1-00d8-5efc-a77b-ebc1d3cddc3c', 'Xin chào công ty, tôi quan tâm đến vị trí này vì môi trường và sản phẩm của công ty. Tôi có thể bắt đầu làm việc sau 2 tuần kể từ khi nhận offer.', '/uploads/cvs/demo-cv-ho-minh-nam.pdf', 'ACCEPTED', '2026-09-16 13:29:02.29+07', 'https://meet.google.com/ptx-kncn-qou', 'Phỏng vấn kỹ thuật 45 phút: trao đổi kinh nghiệm và làm bài tập ngắn.', '2026-09-13 13:29:02.29+07', '2026-09-15 13:29:02.29+07');
INSERT INTO public.project_applications VALUES ('2e34e6a8-1f10-5275-91ca-2eda002f7f87', 'ff1fadb5-4c86-5ddb-b63f-da5a65bdded7', '036af949-a6b8-5f00-be6a-5cbc4493b472', 'Chào anh/chị, em đã đọc kỹ mô tả công việc và thấy kỹ năng của mình phù hợp với vị trí này. Em đính kèm hồ sơ và rất mong có cơ hội trao đổi thêm. Em xin cảm ơn.', '/uploads/cvs/demo-cv-pham-bao-vy.pdf', 'REJECTED', '2026-09-17 19:27:48.043+07', 'https://meet.google.com/yhv-jbju-mjl', 'Phỏng vấn kỹ thuật 45 phút: trao đổi kinh nghiệm và làm bài tập ngắn.', '2026-09-14 19:27:48.043+07', '2026-09-16 19:27:48.043+07');
INSERT INTO public.project_applications VALUES ('400f5cc8-2419-52ad-b4ce-27df528d14d8', 'ff1fadb5-4c86-5ddb-b63f-da5a65bdded7', 'b2823c36-e80c-5c03-b619-998909028ebb', 'Chào anh/chị, em đã đọc kỹ mô tả công việc và thấy kỹ năng của mình phù hợp với vị trí này. Em đính kèm hồ sơ và rất mong có cơ hội trao đổi thêm. Em xin cảm ơn.', '/uploads/cvs/demo-cv-bui-quoc-dung.pdf', 'REJECTED', NULL, NULL, NULL, '2026-09-16 21:12:37.806+07', '2026-09-18 21:12:37.806+07');
INSERT INTO public.project_applications VALUES ('bef46ff8-68fc-5cc3-b213-b7e6c00dab61', '411b541e-b66c-5ddb-b47d-22fb49127c83', '2adcc556-aa24-5982-8500-6093ef6054c0', 'Chào anh/chị, em đã đọc kỹ mô tả công việc và thấy kỹ năng của mình phù hợp với vị trí này. Em đính kèm hồ sơ và rất mong có cơ hội trao đổi thêm. Em xin cảm ơn.', '/uploads/cvs/demo-cv-vu-bao-lan.pdf', 'ACCEPTED', '2026-09-17 22:51:13.421+07', 'https://meet.google.com/jxa-hobx-ihs', 'Phỏng vấn kỹ thuật 45 phút: trao đổi kinh nghiệm và làm bài tập ngắn.', '2026-09-14 22:51:13.421+07', '2026-09-16 22:51:13.421+07');
INSERT INTO public.project_applications VALUES ('e22b9496-f6c3-5898-ad07-ae1fdbdea94d', '411b541e-b66c-5ddb-b47d-22fb49127c83', '94aa8f88-8561-5ee9-9702-7934d7c631fa', 'Chào anh/chị, em đã đọc kỹ mô tả công việc và thấy kỹ năng của mình phù hợp với vị trí này. Em đính kèm hồ sơ và rất mong có cơ hội trao đổi thêm. Em xin cảm ơn.', '/uploads/cvs/demo-cv-vo-kim-thao.pdf', 'REJECTED', NULL, NULL, NULL, '2026-09-15 13:33:32.715+07', '2026-09-17 13:33:32.715+07');
INSERT INTO public.project_applications VALUES ('5a2c9aa9-470f-560d-92f9-a183cf0cc6d9', '411b541e-b66c-5ddb-b47d-22fb49127c83', 'b3212b75-475c-5f23-9cf8-5ed72f4baac5', 'Xin chào công ty, tôi quan tâm đến vị trí này vì môi trường và sản phẩm của công ty. Tôi có thể bắt đầu làm việc sau 2 tuần kể từ khi nhận offer.', '/uploads/cvs/demo-cv-nguyen-hoang-dat.pdf', 'REJECTED', NULL, NULL, NULL, '2026-09-11 01:37:46.69+07', '2026-09-13 01:37:46.69+07');
INSERT INTO public.project_applications VALUES ('ffdac154-c79e-5aa5-b0a7-1f6f5114bd5a', '411b541e-b66c-5ddb-b47d-22fb49127c83', 'e054edcb-a716-5cf7-b9aa-35c12595b4f0', 'Xin chào công ty, tôi quan tâm đến vị trí này vì môi trường và sản phẩm của công ty. Tôi có thể bắt đầu làm việc sau 2 tuần kể từ khi nhận offer.', '/uploads/cvs/demo-cv-ngo-huu-phuc.pdf', 'REJECTED', NULL, NULL, NULL, '2026-09-16 21:04:15.026+07', '2026-09-18 21:04:15.026+07');
INSERT INTO public.project_applications VALUES ('0a99d12b-3095-5d48-9916-52610cb008b7', '3160a518-9c67-5efd-8034-3e6a8cabb123', '0cb1bb9a-e61d-5321-8419-cdcd0e308f37', 'Kính gửi nhà tuyển dụng, tôi có kinh nghiệm thực tế với các công nghệ trong yêu cầu và mong muốn được đóng góp cho đội ngũ. Rất mong nhận được phản hồi từ quý công ty.', '/uploads/cvs/demo-cv-nguyen-anh-hai.pdf', 'ACCEPTED', '2026-09-15 09:15:26.095+07', 'https://meet.google.com/vxn-otjl-wfs', 'Phỏng vấn kỹ thuật 45 phút: trao đổi kinh nghiệm và làm bài tập ngắn.', '2026-09-12 09:15:26.095+07', '2026-09-14 09:15:26.095+07');
INSERT INTO public.project_applications VALUES ('9a8c6b96-3da4-5281-89ec-2b31f0d0547b', '3160a518-9c67-5efd-8034-3e6a8cabb123', '181a28cf-88e2-5502-af20-4c391e6463e4', 'Kính gửi nhà tuyển dụng, tôi có kinh nghiệm thực tế với các công nghệ trong yêu cầu và mong muốn được đóng góp cho đội ngũ. Rất mong nhận được phản hồi từ quý công ty.', '/uploads/cvs/demo-cv-ngo-kim-thao.pdf', 'REJECTED', NULL, NULL, NULL, '2026-09-14 03:20:17.749+07', '2026-09-16 03:20:17.749+07');
INSERT INTO public.project_applications VALUES ('ae2c7684-1a8a-517e-a4f8-c24778fd2eaf', '3160a518-9c67-5efd-8034-3e6a8cabb123', 'e02ee5a3-bb7f-539e-8ec8-0abd89329011', 'Kính gửi nhà tuyển dụng, tôi có kinh nghiệm thực tế với các công nghệ trong yêu cầu và mong muốn được đóng góp cho đội ngũ. Rất mong nhận được phản hồi từ quý công ty.', '/uploads/cvs/demo-cv-dang-duc-tin.pdf', 'REJECTED', NULL, NULL, NULL, '2026-09-12 10:34:13.93+07', '2026-09-14 10:34:13.93+07');
INSERT INTO public.project_applications VALUES ('b44c9ed5-6c75-59a6-8be3-6b6e1f765c35', '1138a599-05bb-5e28-b129-0002cf99ca32', 'fd26b374-6ff8-5831-92ec-b2df993bc8f1', 'Em chào anh/chị. Em là người ham học hỏi, từng tham gia một số dự án có công nghệ tương tự yêu cầu. Em sẵn sàng làm bài kiểm tra hoặc phỏng vấn vào thời gian anh/chị thuận tiện.', NULL, 'ACCEPTED', '2026-09-16 20:26:27.342+07', 'https://meet.google.com/prc-xcqf-wwn', 'Phỏng vấn kỹ thuật 45 phút: trao đổi kinh nghiệm và làm bài tập ngắn.', '2026-09-13 20:26:27.342+07', '2026-09-15 20:26:27.342+07');
