INSERT INTO public.project_applications VALUES ('95b5e4e5-23a8-54f1-98ac-6ec3c9c742c1', '1169cc95-8ff5-57ab-b8cc-8b82905c3584', '324f8f18-84b0-5b2b-9069-7e7f42c49fe4', 'Chào anh/chị, em đã đọc kỹ mô tả công việc và thấy kỹ năng của mình phù hợp với vị trí này. Em đính kèm hồ sơ và rất mong có cơ hội trao đổi thêm. Em xin cảm ơn.', '/uploads/cvs/demo-cv-pham-minh-quan.pdf', 'REVIEWING', NULL, NULL, NULL, '2026-10-26 09:45:26.054+07', '2026-10-28 09:45:26.054+07');
