INSERT INTO public.project_applications VALUES ('5c8f5447-cdb0-5d78-a5a0-45a8ed331342', '76a0480e-9a5c-5f74-8c56-dc46d3efafcd', 'e054edcb-a716-5cf7-b9aa-35c12595b4f0', 'Em chào anh/chị. Em là người ham học hỏi, từng tham gia một số dự án có công nghệ tương tự yêu cầu. Em sẵn sàng làm bài kiểm tra hoặc phỏng vấn vào thời gian anh/chị thuận tiện.', '/uploads/cvs/demo-cv-ngo-huu-phuc.pdf', 'PENDING', NULL, NULL, NULL, '2026-10-29 08:15:51.547+07', '2026-10-31 00:19:13.97+07');
INSERT INTO public.project_applications VALUES ('c3fb4bdd-3642-52b8-9530-411f8afcc6a6', '76a0480e-9a5c-5f74-8c56-dc46d3efafcd', '2adcc556-aa24-5982-8500-6093ef6054c0', NULL, '/uploads/cvs/demo-cv-vu-bao-lan.pdf', 'PENDING', NULL, NULL, NULL, '2026-10-30 05:21:12.815+07', '2026-10-31 00:19:13.97+07');
INSERT INTO public.project_applications VALUES ('6d18bea6-0a02-5c2a-8fd4-39fb56ebdc35', '76a0480e-9a5c-5f74-8c56-dc46d3efafcd', '94aa8f88-8561-5ee9-9702-7934d7c631fa', 'Kính gửi nhà tuyển dụng, tôi có kinh nghiệm thực tế với các công nghệ trong yêu cầu và mong muốn được đóng góp cho đội ngũ. Rất mong nhận được phản hồi từ quý công ty.', '/uploads/cvs/demo-cv-vo-kim-thao.pdf', 'REVIEWING', NULL, NULL, NULL, '2026-10-28 07:52:43.221+07', '2026-10-30 07:52:43.221+07');
