INSERT INTO public.projects VALUES ('5a67fe4f-871b-4303-bcbf-ea3d7a0d6718', 'Hệ thống Quản lý kho Logistics (DevHub Client)', 'Xây dựng toàn diện ứng dụng web quản lý nhập, xuất, tồn kho hàng hóa và tích hợp mã QR.', 30000000.00, '2026-09-26', '2026-11-10', NULL, 'RECRUITING', 60.00, 'db7c670f-1493-4391-8c34-722b0e3a487e', NULL, '2026-09-26 17:32:17.259+07', '2026-10-23 23:43:48.881+07');
INSERT INTO public.projects VALUES ('14668d15-3f94-5145-9598-5494d7a88eb9', 'Hệ thống đặt lịch khám bệnh trực tuyến', 'Xây dựng web và ứng dụng cho phép bệnh nhân tìm bác sĩ theo chuyên khoa, đặt/hủy lịch khám, nhận nhắc lịch qua email và SMS. Phía phòng khám có trang quản lý lịch làm việc của bác sĩ và thống kê lượt khám.', 85000000.00, '2026-09-19', '2026-12-08', NULL, 'IN_PROGRESS', 47.00, 'db7c670f-1493-4391-8c34-722b0e3a487e', NULL, '2026-09-13 00:20:13.97+07', '2026-09-13 00:20:13.97+07');
INSERT INTO public.projects VALUES ('46895d2e-dc84-5790-8acb-3c3cabc881d7', 'Ứng dụng di động theo dõi chi tiêu cá nhân', 'Ứng dụng Flutter giúp người dùng ghi chép thu chi, đặt ngân sách theo danh mục, nhận cảnh báo khi vượt hạn mức và xem báo cáo theo tuần/tháng. Backend Node.js đồng bộ dữ liệu giữa nhiều thiết bị.', 60000000.00, '2026-06-28', '2026-10-06', '2026-10-09', 'COMPLETED', 100.00, 'db7c670f-1493-4391-8c34-722b0e3a487e', NULL, '2026-06-22 00:20:13.97+07', '2026-10-09 00:20:13.97+07');
INSERT INTO public.projects VALUES ('bb1ebe49-4309-577a-a39b-b2a4c6fe1c4d', 'Chatbot hỗ trợ luyện tiếng Anh (MVP)', 'Xây dựng bản MVP chatbot giúp người học luyện hội thoại tiếng Anh theo chủ đề, tự động sửa lỗi ngữ pháp và đánh giá mức độ trôi chảy. Gồm API Python, giao diện chat web và bộ kiểm thử chất lượng phản hồi.', 55000000.00, '2026-10-05', '2026-12-10', NULL, 'IN_PROGRESS', 30.00, 'db7c670f-1493-4391-8c34-722b0e3a487e', NULL, '2026-09-29 00:20:13.97+07', '2026-09-29 00:20:13.97+07');
INSERT INTO public.projects VALUES ('f5e71b1e-16cc-5bdd-afba-a7d341db24db', 'Website thương mại điện tử thời trang', 'Website bán hàng thời trang cho thương hiệu có 5 cửa hàng: danh mục sản phẩm, giỏ hàng, thanh toán, quản lý kho theo chi nhánh và trang quản trị doanh thu.', 48000000.00, '2026-04-04', '2026-09-01', '2026-09-03', 'COMPLETED', 100.00, 'db7c670f-1493-4391-8c34-722b0e3a487e', NULL, '2026-03-29 00:20:13.97+07', '2026-09-03 00:20:13.97+07');
INSERT INTO public.projects VALUES ('52763bf1-ab11-5c7a-b11d-4fcdff1df918', 'Cổng thông tin tuyển sinh trực tuyến', 'Cổng đăng ký xét tuyển trực tuyến cho trường cao đẳng: nộp hồ sơ, tra cứu kết quả, thanh toán lệ phí và trang quản trị dành cho phòng đào tạo.', 70000000.00, '2026-10-25', '2027-01-14', NULL, 'RECRUITING', 0.00, 'db7c670f-1493-4391-8c34-722b0e3a487e', NULL, '2026-10-19 00:20:13.97+07', '2026-10-19 00:20:13.97+07');
INSERT INTO public.projects VALUES ('1cf9f653-b737-5d9d-9adb-6949b8c96b2c', 'Dashboard phân tích dữ liệu bán lẻ', 'Xây dựng kho dữ liệu nhỏ và bộ dashboard giúp chuỗi bán lẻ theo dõi doanh thu, tồn kho và hiệu quả khuyến mãi theo thời gian thực.', 40000000.00, '2026-10-30', '2027-01-29', NULL, 'PLANNING', 0.00, 'db7c670f-1493-4391-8c34-722b0e3a487e', NULL, '2026-10-24 00:20:13.97+07', '2026-10-24 00:20:13.97+07');
